<?php
/**
 * home_video.php — the homepage demo video, and every rule about it.
 *
 * One place decides:
 *   - which YouTube URL forms are accepted, and which video id comes out;
 *   - what the section shows when nothing is configured, or the video is gone;
 *   - how the admin's values are validated before they reach the database.
 *
 * Why a separate file: home.php is generated by tools/build-home.mjs, and the
 * owner panel page is a different page with a different session. Both need the
 * same rules, so the rules live here and nowhere else.
 *
 * Rules of the house, same as links.php:
 *   - a YouTube id is the ONLY thing that reaches the embed URL. There is no
 *     "paste an iframe" field anywhere, so nobody can inject markup;
 *   - anything that is not a YouTube link is refused, not repaired;
 *   - an empty value always means "not configured", never a fallback video;
 *   - nothing here invents a thumbnail: custom → YouTube's own → the built-in
 *     ReviewAI card, in that order.
 */

require_once __DIR__ . '/functions.php';
require_once __DIR__ . '/links.php';

/* ------------------------------------------------------------------ defaults */

/** Longest title the section will show. Longer than this is not a title. */
const RG_HOME_VIDEO_TITLE_MAX = 120;

/** Longest description the section will show. */
const RG_HOME_VIDEO_DESC_MAX = 300;

/** Longest URL we will store (same limit as the rest of the app). */
const RG_HOME_VIDEO_URL_MAX = RG_URL_MAX_LENGTH;

/** Upload limit for the custom thumbnail: 3 MB, and 16:9 is recommended. */
const RG_HOME_VIDEO_THUMB_MAX_BYTES = 3 * 1024 * 1024;

function rg_home_video_defaults(): array
{
    return [
        'enabled'     => false,
        'url'         => '',
        'video_id'    => '',
        'title'       => 'How to Set Up ReviewAI for Your Business',
        'description' => 'Learn how to set up your business, generate your QR code and collect customer feedback in minutes.',
        'channel_url' => '',
        'thumbnail'   => '',
    ];
}

/* ------------------------------------------------------- youtube id parsing */

/**
 * Extracts a YouTube video id from the URL forms a human actually pastes.
 *
 * Accepted:
 *   https://www.youtube.com/watch?v=VIDEO_ID          (v may sit anywhere)
 *   https://youtu.be/VIDEO_ID
 *   https://www.youtube.com/embed/VIDEO_ID
 *   https://www.youtube.com/shorts/VIDEO_ID
 *   https://www.youtube.com/live/VIDEO_ID
 *   https://m.youtube.com/watch?v=…, https://music.youtube.com/watch?v=…
 *   a bare VIDEO_ID (11 characters)
 *
 * Returns '' for everything else. A watch page whose v= is missing or too short
 * is not a video, and a link to another site is not a YouTube video at all.
 */
function rg_youtube_video_id(string $input): string
{
    $input = trim($input);
    if ($input === '' || strlen($input) > RG_HOME_VIDEO_URL_MAX) return '';

    $idPattern = '/^[A-Za-z0-9_-]{11}$/';

    /* A bare id, typed without any URL around it. */
    if (preg_match($idPattern, $input)) return $input;

    /* Protocol-relative and scheme-less forms are accepted for convenience; the
       parser below is the only thing that decides the id, never the string. */
    $candidate = $input;
    if (strpos($candidate, '//') === 0) $candidate = 'https:' . $candidate;

    $parts = @parse_url($candidate);
    if (!$parts || empty($parts['host'])) {
        /* No scheme at all, e.g. "youtube.com/watch?v=…". */
        $parts = @parse_url('https://' . ltrim($candidate, '/'));
    }
    if (!$parts || empty($parts['host'])) return '';

    if (!empty($parts['scheme']) && !in_array(strtolower($parts['scheme']), ['http', 'https'], true)) {
        return '';
    }

    $host = strtolower($parts['host']);
    $host = preg_replace('/^www\./', '', $host);
    $host = preg_replace('/^m\./', '', $host);
    $host = preg_replace('/^music\./', '', $host);

    $youtubeHosts = ['youtube.com', 'youtu.be', 'youtube-nocookie.com', 'youtube.co.uk'];
    if (!in_array($host, $youtubeHosts, true)) return '';

    /* youtu.be/ID — the whole path is the id. */
    if ($host === 'youtu.be') {
        $path = trim((string)($parts['path'] ?? ''), '/');
        return preg_match($idPattern, $path) ? $path : '';
    }

    /* /embed/ID, /shorts/ID, /live/ID, /v/ID */
    if (preg_match('#^/(?:embed|shorts|live|v)/([A-Za-z0-9_-]{11})(?:[/?]|$)#', (string)($parts['path'] ?? ''), $m)) {
        return $m[1];
    }

    /* /watch?v=ID — the query is parsed, not string-matched. */
    if (!empty($parts['query'])) {
        $query = [];
        parse_str($parts['query'], $query);
        if (isset($query['v']) && preg_match($idPattern, (string)$query['v'])) {
            return (string)$query['v'];
        }
    }

    return '';
}

/** The public watch page for an id. Built from the id, never from stored HTML. */
function rg_youtube_watch_url(string $videoId): string
{
    return preg_match('/^[A-Za-z0-9_-]{11}$/', $videoId) === 1
        ? 'https://www.youtube.com/watch?v=' . $videoId
        : '';
}

/**
 * The embed URL the page will use once the visitor presses play.
 *
 * youtube-nocookie.com keeps YouTube from dropping advertising cookies before
 * the visitor has asked for the video. The id is the only variable.
 */
function rg_youtube_embed_url(string $videoId): string
{
    if (preg_match('/^[A-Za-z0-9_-]{11}$/', $videoId) !== 1) return '';
    return 'https://www.youtube-nocookie.com/embed/' . $videoId
         . '?autoplay=1&rel=0&modestbranding=1&playsinline=1';
}

/** YouTube's own preview image. hqdefault always exists, even for new videos. */
function rg_youtube_thumb_url(string $videoId, string $quality = 'hqdefault'): string
{
    if (preg_match('/^[A-Za-z0-9_-]{11}$/', $videoId) !== 1) return '';
    $allowed = ['default', 'mqdefault', 'hqdefault', 'sddefault', 'maxresdefault'];
    if (!in_array($quality, $allowed, true)) $quality = 'hqdefault';
    return 'https://i.ytimg.com/vi/' . $videoId . '/' . $quality . '.jpg';
}

/**
 * A channel / playlist destination for the "Watch on YouTube" button.
 *
 * Accepts any youtube.com or youtu.be URL the owner pastes (channel, @handle,
 * /c/, /channel/UC…, a playlist). Anything else is refused: the button must never
 * become a redirect to a third-party site.
 */
function rg_youtube_channel_url(string $input): string
{
    $safe = rg_safe_url($input, 'home_video_channel_url');
    if ($safe === '') return '';

    $host = strtolower((string)parse_url($safe, PHP_URL_HOST));
    $host = preg_replace('/^www\.|^m\./', '', $host);
    if (!in_array($host, ['youtube.com', 'youtu.be', 'music.youtube.com'], true)) return '';

    return $safe;
}

/* ---------------------------------------------------------------- settings */

/**
 * The current configuration, with defaults applied and everything re-checked.
 *
 * The stored video id is trusted only after it passes the same regex the parser
 * uses, so a hand-edited database row cannot produce a broken embed.
 */
function rg_home_video_settings(): array
{
    $defaults = rg_home_video_defaults();

    $storedId = trim((string)getSetting('home_video_id', ''));
    $storedUrl = trim((string)getSetting('home_video_url', ''));

    /* The URL is the source of truth; the id is a cache. If they disagree (an
       older row, a hand edit), the URL wins and the id is re-derived. */
    $videoId = rg_youtube_video_id($storedUrl);
    if ($videoId === '' && preg_match('/^[A-Za-z0-9_-]{11}$/', $storedId)) {
        $videoId = $storedId;
    }

    $title = trim((string)getSetting('home_video_title', $defaults['title']));
    if ($title === '') $title = $defaults['title'];
    if (function_exists('mb_substr')) $title = mb_substr($title, 0, RG_HOME_VIDEO_TITLE_MAX);
    else $title = substr($title, 0, RG_HOME_VIDEO_TITLE_MAX);

    $description = trim((string)getSetting('home_video_description', $defaults['description']));
    if ($description === '') $description = $defaults['description'];
    if (function_exists('mb_substr')) $description = mb_substr($description, 0, RG_HOME_VIDEO_DESC_MAX);
    else $description = substr($description, 0, RG_HOME_VIDEO_DESC_MAX);

    $channelUrl = rg_youtube_channel_url((string)getSetting('home_video_channel_url', ''));

    /* Custom thumbnail: a relative path inside assets/uploads that must still
       exist on disk. A row pointing at a deleted file falls back, not breaks. */
    $thumbRaw = trim((string)getSetting('home_video_thumbnail', ''));
    $thumbPath = '';
    if ($thumbRaw !== '') {
        if (preg_match('#^assets/uploads/[A-Za-z0-9._-]+$#', $thumbRaw) === 1) {
            $absolute = __DIR__ . '/../' . $thumbRaw;
            if (is_file($absolute)) $thumbPath = $thumbRaw;
        }
    }

    $thumbnailKind = 'default';
    $thumbnailUrl  = '';
    if ($thumbPath !== '') {
        $thumbnailKind = 'custom';
        $thumbnailUrl  = url($thumbPath);
    } elseif ($videoId !== '') {
        $thumbnailKind = 'youtube';
        $thumbnailUrl  = rg_youtube_thumb_url($videoId);
    }

    /* Where the button goes: the configured channel if there is one, otherwise
       the video itself. Nothing is invented when both are missing. */
    $watchUrl = '';
    if ($channelUrl !== '') {
        $watchUrl = $channelUrl;
    } elseif ($videoId !== '') {
        $watchUrl = rg_youtube_watch_url($videoId);
    }

    return [
        'enabled'        => (string)getSetting('home_video_enabled', '0') === '1',
        'url'            => $storedUrl,
        'video_id'       => $videoId,
        'title'          => $title,
        'description'    => $description,
        'channel_url'    => $channelUrl,
        'thumbnail'      => $thumbPath,
        'thumbnail_kind' => $thumbnailKind,
        'thumbnail_url'  => $thumbnailUrl,
        'embed_url'      => rg_youtube_embed_url($videoId),
        'watch_url'      => $watchUrl,
        'has_video'      => $videoId !== '',
    ];
}

/* ------------------------------------------------------------- admin saving */

/**
 * Validates and stores the owner's video settings.
 *
 * Returns ['ok' => bool, 'errors' => [field => message], 'saved' => [...]].
 * Nothing is written unless every field passes: a half-saved configuration is
 * how a homepage ends up with a dead player.
 *
 * The thumbnail is not moved here — owner_homepage.php does that with the same
 * validated extension and then calls this function with the stored path.
 */
function rg_home_video_save(array $input, string $newThumbnail = '', bool $removeThumbnail = false): array
{
    $errors = [];
    $current = rg_home_video_settings();

    $rawUrl = trim((string)($input['url'] ?? ''));
    $enabled = !empty($input['enabled']);

    $videoId = rg_youtube_video_id($rawUrl);
    if ($rawUrl === '') {
        $videoId = '';
    } elseif ($videoId === '') {
        $errors['url'] = 'That is not a YouTube video link. Paste a link like https://www.youtube.com/watch?v=… or https://youtu.be/…';
    }

    $title = trim((string)($input['title'] ?? ''));
    if ($title === '') {
        $title = rg_home_video_defaults()['title'];
    }
    if (strlen($title) > RG_HOME_VIDEO_TITLE_MAX * 4) {
        $errors['title'] = 'The video title is too long.';
    }

    $description = trim((string)($input['description'] ?? ''));
    if ($description === '') {
        $description = rg_home_video_defaults()['description'];
    }
    if (strlen($description) > RG_HOME_VIDEO_DESC_MAX * 4) {
        $errors['description'] = 'The description is too long.';
    }

    $rawChannel = trim((string)($input['channel_url'] ?? ''));
    $channelUrl = '';
    if ($rawChannel !== '') {
        $channelUrl = rg_youtube_channel_url($rawChannel);
        if ($channelUrl === '') {
            $errors['channel_url'] = 'That is not a YouTube link. Use https://www.youtube.com/@yourchannel or a youtube.com address.';
        }
    }

    /* Enabling with no video would publish an empty player. Refuse it. */
    if ($enabled && $videoId === '') {
        $errors['url'] = $errors['url']
            ?? 'Add a YouTube video link before switching the section on.';
    }

    if ($errors) {
        return ['ok' => false, 'errors' => $errors, 'saved' => $current];
    }

    if ($removeThumbnail) {
        $oldPath = $current['thumbnail'];
        if ($oldPath !== '') {
            $absolute = __DIR__ . '/../' . $oldPath;
            if (is_file($absolute)) @unlink($absolute);
        }
        $newThumbnail = '';
    } elseif ($newThumbnail === '') {
        $newThumbnail = $current['thumbnail'];
    }

    setSetting('home_video_url', $rawUrl);
    setSetting('home_video_id', $videoId);
    setSetting('home_video_title', $title);
    setSetting('home_video_description', $description);
    setSetting('home_video_channel_url', $channelUrl);
    setSetting('home_video_thumbnail', $newThumbnail);
    setSetting('home_video_enabled', $enabled ? '1' : '0');

    return ['ok' => true, 'errors' => [], 'saved' => rg_home_video_settings()];
}

/* ----------------------------------------------------------- thumbnail file */

/**
 * Checks an uploaded thumbnail the way card_update_settings.php checks a logo.
 *
 * The file must really be an image (getimagesize reads the header, so a .php
 * renamed to .png fails), the extension comes from the detected type and never
 * from the name the browser sent, and the size is capped.
 *
 * Returns ['ok' => bool, 'ext' => 'png', 'error' => ''].
 */
function rg_home_video_validate_thumb(string $tmpPath, int $size): array
{
    if ($tmpPath === '' || !is_file($tmpPath)) {
        return ['ok' => false, 'ext' => '', 'error' => 'No file was uploaded.'];
    }
    if ($size <= 0) {
        return ['ok' => false, 'ext' => '', 'error' => 'The file is empty.'];
    }
    if ($size > RG_HOME_VIDEO_THUMB_MAX_BYTES) {
        return ['ok' => false, 'ext' => '', 'error' => 'The thumbnail must be 3 MB or smaller.'];
    }

    $info = @getimagesize($tmpPath);
    $allowed = [
        IMAGETYPE_JPEG => 'jpg',
        IMAGETYPE_PNG  => 'png',
        IMAGETYPE_GIF  => 'gif',
        IMAGETYPE_WEBP => 'webp',
    ];
    $ext = ($info && isset($allowed[$info[2]])) ? $allowed[$info[2]] : '';

    if ($ext === '') {
        return ['ok' => false, 'ext' => '', 'error' => 'The thumbnail must be a JPEG, PNG, GIF or WebP image.'];
    }

    return ['ok' => true, 'ext' => $ext, 'error' => '', 'width' => (int)$info[0], 'height' => (int)$info[1]];
}

/** The stored filename. The upload's own name never reaches the filesystem. */
function rg_home_video_thumb_name(string $ext): string
{
    $allowed = ['jpg', 'png', 'gif', 'webp'];
    if (!in_array($ext, $allowed, true)) $ext = 'jpg';
    return 'home-video-' . bin2hex(random_bytes(8)) . '.' . $ext;
}

/* --------------------------------------------------------------- the render */

/**
 * Prints the homepage section.
 *
 * Nothing is printed when the section is switched off, or when it is switched on
 * but no usable video id has been stored yet: a public page must never show an
 * empty player or a dead button.
 */
function rg_home_video_render(): void
{
    $v = rg_home_video_settings();
    if (!$v['enabled'] || !$v['has_video']) return;

    $titleEsc = e($v['title']);
    $descEsc  = e($v['description']);
    $embedEsc = e($v['embed_url']);
    $watchEsc = e($v['watch_url']);
    $hasWatch = $v['watch_url'] !== '';

    /* The poster: the owner's own image, YouTube's preview, or the built-in
       ReviewAI card. The last one is markup, so it needs no file and can never
       be a broken image. */
    if ($v['thumbnail_kind'] === 'custom') {
        $poster = '<img class="rg-video-poster-img" src="' . e($v['thumbnail_url']) . '" alt="" width="1280" height="720" loading="lazy" decoding="async">';
    } elseif ($v['thumbnail_kind'] === 'youtube') {
        $poster = '<img class="rg-video-poster-img" src="' . e($v['thumbnail_url']) . '" alt="" width="1280" height="720" loading="lazy" decoding="async"'
                . ' data-rg-poster-fallback="1">';
    } else {
        $poster = '';
    }

    $posterImg = $poster;
    ?>
<section class="rg-video-section" id="demo" aria-labelledby="rgVideoHeading">
  <span class="rg-video-spark s1" aria-hidden="true">✦</span>
  <span class="rg-video-spark s2" aria-hidden="true">✧</span>
  <span class="rg-video-spark s3" aria-hidden="true">✦</span>

  <div class="rg-video-inner">
    <span class="rg-video-badge"><span class="rg-video-badge-tri" aria-hidden="true">▶</span> Watch Demo</span>

    <h2 class="rg-video-heading" id="rgVideoHeading">See How <em>ReviewAI</em> Works</h2>
    <p class="rg-video-lead"><?= $descEsc ?></p>

    <div class="rg-video-frame">
      <div class="rg-video-player" id="rgVideoPlayer"
           data-embed="<?= $embedEsc ?>"
           data-title="<?= $titleEsc ?>"
           data-watch="<?= $watchEsc ?>">
        <button class="rg-video-poster" type="button" id="rgVideoPlay" aria-label="Play the video: <?= $titleEsc ?>">
          <?php if ($posterImg !== ''): ?>
            <?= $posterImg ?>
          <?php endif; ?>
          <span class="rg-video-default<?= $posterImg !== '' ? ' is-hidden' : '' ?>" aria-hidden="true">
            <span class="rg-video-default-brand"><span class="rg-video-default-mark">✳</span> ReviewAI</span>
            <span class="rg-video-default-copy">
              <strong>Complete Setup Guide</strong>
              <span>in 2 Minutes</span>
            </span>
            <span class="rg-video-phone" aria-hidden="true">
              <span class="rg-video-phone-bar"></span>
              <span class="rg-video-phone-kicker">✳ Review AI</span>
              <span class="rg-video-phone-line w70"></span>
              <span class="rg-video-phone-line w90"></span>
              <span class="rg-video-phone-line w55"></span>
              <span class="rg-video-phone-stars">★★★★★</span>
              <span class="rg-video-phone-button">Create a draft →</span>
            </span>
          </span>
          <span class="rg-video-play" aria-hidden="true">
            <span class="rg-video-play-tri">▶</span>
          </span>
        </button>
        <div class="rg-video-slot" id="rgVideoSlot" hidden></div>
        <p class="rg-video-error" id="rgVideoError" hidden role="status"></p>
      </div>
      <p class="rg-video-caption"><?= $titleEsc ?></p>
    </div>

    <?php if ($hasWatch): ?>
    <div class="rg-video-actions">
      <a class="rg-video-cta" href="<?= $watchEsc ?>" target="_blank" rel="noopener noreferrer">
        Watch on YouTube <span aria-hidden="true">↗</span>
      </a>
      <span class="rg-video-note">Quick 2-Minute Tutorial</span>
    </div>
    <?php else: ?>
    <div class="rg-video-actions">
      <span class="rg-video-note">Quick 2-Minute Tutorial</span>
    </div>
    <?php endif; ?>
  </div>
</section>
    <?php
}
